The optimal solution of $\mathbf{P}_{{1}}$ can be obtained if and only if the following equation holds.
\begin{subequations}
\begin{align}\label{27}\
&{\mathop {\max }\limits_{{\tau _0},{\tau _k},{P_k},{f_k}} }\ {\mathop {\min }\limits_{k \in{\cal K}}}\ R_k\left( {{\tau _k},{P_k},{f_k}} \right)-\eta^{*}E_k\left( {\tau _0, {\tau _k},{P_k},{f_k}} \right)\\
&= {\mathop {\min }\limits_{k \in{\cal K}}}\ R_k\left( {{\tau _k^{*}},{P_k^{*}},{f_k^{*}}} \right)-\eta^{*}E_k\left( {\tau _0^{*}, {\tau _k}^{*},{P_k}^{*},{f_k^{*}}} \right)=0,
\end{align}
\end{subequations}

In the wireless powered MEC systems with TDMA, the optimal local computation frequency $f_k^{*}$ and the optimal offloading power $P_k^{*}$ of the $k$th user for maximizing the CE under the max-min fairness criterion have the following mathematical expressions:
\begin{subequations}
\begin{align}\label{27}\
&f_k^{*} = \sqrt {\frac{{{\lambda _k} + {\theta _k}}}{{3C{\gamma _c}\left( {{\rho _k} + {\theta _k}\eta } \right)}}};\\
&P_k^{*} = \left\{ \begin{array}{l}
\begin{array}{*{20}{c}}
{0,}&{\text{if}\ {\tau _k} = 0}
\end{array}\\
\begin{array}{*{20}{c}}
{{{\left[ {\frac{{\left( {{\lambda _k} + {\theta _k}} \right)B}}{{\zeta{v_k}\ln 2\left( {{\rho _k} + {\theta _k}\eta } \right)}} - \frac{{\sigma _0^2}}{{{g_k}}}} \right]}^ + },}&{\text{otherwise}};
\end{array}
\end{array} \right.
\end{align}
\end{subequations}
where $\lambda _k\geq0$, $\rho _k\geq0$ and $\theta _k\geq0$ are the dual variables corresponding to the constraints given by $\left(7\rm{b}\right)$, $\left(7\rm{c}\right)$, and $\left(7\rm{d}\right)$,  respectively.

For  the given $\lambda _k$, $\rho _k$, $\beta$ and $\theta _k$, in order to maximize the Lagrangian of $\mathbf{P}_{{3}}$, the optimal EH time $\tau_0^{*}$ and computation offloading time $\tau_k^{*}$ need to satisfy the following equations.
\begin{subequations}
\begin{align}\label{27}\
&\tau _0^{*} = \left\{ \begin{array}{l}
\begin{array}{*{20}{c}}
{0,}&{\text{if}\ z\left( {{\rho _k},\beta ,{\theta _k}} \right) < 0},
\end{array}\\
\begin{array}{*{20}{c}}
{ \in \left[ {0,T} \right),}&{\text{if} \ z\left( {{\rho _k},\beta ,{\theta _k}} \right) = 0},
\end{array}
\end{array} \right.
\\
&z\left( {{\rho _k},\beta ,{\theta _k}} \right) = \sum\limits_{k = 1}^K {{\rho _k}} \left( {{P_{E,k}} - {P_{r,k}}} \right) - \beta  - \sum\limits_{k = 1}^K {{\theta _k}\eta } {P_{r,k}},\\
&{P_{E,k}} ={\frac{{P_k^{\max }}}{{\exp \left( { - \mu {P_0} + \psi } \right)}}\left( {\frac{{1 + \exp \left( { - \mu {P_0} + \psi } \right)}}{{1 + \exp \left( { - \mu {h_k}{P_{th}} + \psi } \right)}} - 1} \right)},
\end{align}
\end{subequations}
\begin{subequations}
\begin{align}\label{27}\
&\tau _k^{*} = \left\{ \begin{array}{l}
\begin{array}{*{20}{c}}
{{\rm Z} ,}&{\text{if} \ \frac{{\sigma _0^2\zeta{v_k}{\theta _k}\eta \ln 2}}{{\left( {{\lambda _k} + {\theta _k}} \right)B}} > \omega^{opt} },
\end{array}\\
\begin{array}{*{20}{c}}
{ \in \left[ {0,{\rm Z} } \right],}&{\text{if} \ \frac{{\sigma _0^2\zeta{v_k}{\theta _k}\eta \ln 2}}{{\left( {{\lambda _k} + {\theta _k}} \right)B}} = \omega^{opt} },
\end{array}\\
\begin{array}{*{20}{c}}
{0,}&{\text{if} \ \frac{{\sigma _0^2\zeta{v_k}{\theta _k}\eta \ln 2}}{{\left( {{\lambda _k} + {\theta _k}} \right)B}} < \omega^{opt} },
\end{array}
\end{array} \right.
\\
&{\rm Z } = \frac{{{\Phi _k}\left( {\tau _0^{opt},{P_{th}}} \right) - \tau _0^{opt}{P_{r,k}} - T{\gamma _c}{{\left( {f_k^{opt}} \right)}^3}}}{{{P_{c,k}} + P_k^{opt}}},
\end{align}
\end{subequations}
where $\omega^{*} $ is the solution of the following equation.
\begin{align}\label{27}\ \notag
&\frac{{B\left( {{\lambda _k} + {\theta _k}} \right)}}{{{v_k}}}{\log _2}\left[ {\frac{{\left( {{\lambda _k} + {\theta _k}} \right)Bw}}{{\zeta{v_k}{\theta _k}\eta \sigma _0^2\ln 2}}} \right] - \frac{{\left( {{\lambda _k} + {\theta _k}} \right)B}}{{{v_k}\ln 2}}\\
&+ \frac{{\zeta\left( {{\rho _k} + {\theta _k}\eta } \right) \sigma _0^2}}{w} - \zeta\left( {{\rho _k} + {\theta _k}\eta } \right) {P_{c,k}} - \beta  = 0.
\end{align}

In the wireless powered MEC systems with TDMA under the partial computation offloading mode, the maximum CE under the max-min fairness criterion is given as
\begin{subequations}
\begin{align}\label{27}\
&\Upsilon ^{*}= \left\{ \begin{array}{l}
\begin{array}{*{20}{c}}
{0,}&{\text{if}\ \sum\limits_{k = 1}^K { {\theta _k}}  > 1,}
\end{array}\\
\begin{array}{*{20}{c}}
{{\Lambda ^*,}}&{\text{if}\ \sum\limits_{k = 1}^K { {\theta _k}}  \le 1;}
\end{array}
\end{array} \right.
\\
&\Lambda ^*={\mathop {\min }\limits_{k \in{\cal K}}}\ R_k\left( {{\tau _k^{*}},{P_k^{*}},{f_k^{*}}} \right)-\eta E_k\left( {\tau _0^{*}, {\tau _k}^{*},{P_k}^{*},{f_k^{*}}} \right),
\end{align}
\end{subequations}

In the wireless powered MEC systems with TDMA under the binary computation offloading mode, the optimal operational mode selection index has the following form
\begin{subequations}
\begin{align}\label{27}\
&{\alpha _k}^{*}= \left\{ \begin{array}{l}
0,\text{if}\ {F_{1,k}} < {F_{2,k}},\\
1,\text{otherwise};
\end{array} \right.
\\ \notag
&{F_{1,k}} = \left( {{\lambda _{{k}}} + {\chi  _k}} \right)\frac{{B{\tau _k}}}{{{v_k}}}{\log _2}\left( {1 + \frac{{{g_k}{{{y}}_k}}}{{{\tau _k}\sigma _0^2}}} \right)\\
 &\ \ \ \ \ \ \ - \zeta \left( {{\mu _k} + {\chi  _k}\eta } \right)\left( {{{{y}}_k} + {\tau _k}{P_{c,k}}} \right) - \upsilon {\tau _k},\\
&{F_{2,k}} = \left( {{\lambda _{{k}}} + {\chi  _k}} \right)\frac{{T{f_k}}}{C} - \left( {{\mu _k} + {\chi  _k}\eta } \right)T{\gamma _c}f_k^3,
\end{align}
\end{subequations}
where $\lambda _{{k}}\geq0$,  $\mu _k\geq0$, $\upsilon\geq0$ and $\chi  _k\geq0$ are the dual variables associated with the constraints given by $\left(18\rm{b}\right)$, $\left(18\rm{c}\right)$, $\left(18\rm{d}\right)$ and $\left(17\rm{d}\right)$.

In the wireless powered MEC systems with NOMA under the binary offloading mode, the optimal operational mode selection index has the form given by eq. (26) in the top of the next page,
\begin{figure*}[!t]
\normalsize
\begin{subequations}
\begin{align}\label{27}\
&{\alpha _k}^{*}= \left\{ \begin{array}{l}
0,\text{if}\ {F_{1,k}} < {F_{2,k}},\\
1,\text{otherwise};
\end{array} \right.
\\
&{F_{k,1}} = \left\{ {\begin{array}{*{20}{c}}
\begin{array}{l}
\begin{array}{*{20}{c}}
{\exp \left( {{d_1}} \right)\left[ {\frac{{{\lambda _k}B}}{{{v_k}}}{{\log }_2}\left( {1 + \frac{{{g_k}\exp \left( {{x_k}} \right)}}{{\sigma _0^2}}} \right) - \left( {{\mu _k} + {\omega _k}\eta } \right)\left( {\exp \left( {{x_k}} \right) + {P_{c,k}}} \right)} \right],}&{k = K}
\end{array}\\
\exp \left( {{d_1}} \right)\left[ {\frac{{{\lambda _k}B}}{{{v_k}}}{{\log }_2}\left( {1 + \frac{{{g_k}\exp \left( {{x_k}} \right)}}{{\sum\limits_{i = k + 1}^K {{g_i}\exp \left( {{x_i}} \right)}  + \sigma _0^2}}} \right) - \zeta \left( {{\mu _k} + {\omega _k}\eta } \right)\left( {\exp \left( {{x_k}} \right) + {P_{c,k}}} \right)} \right],\text{otherwise}
\end{array}
\end{array}} \right.\\
&{F_{k,2}} = \left( {{\varpi _{{k}}} + {\omega _k}} \right)\frac{{T{f_k}}}{C} - \left( {{\mu _k} + {\omega _k}\eta } \right)T{\gamma _c}f_k^3,
\end{align}
\end{subequations}
\hrulefill \vspace*{4pt}
\end{figure*}
where $\varpi _{{k}}\geq0$, $\lambda _{{k}}\geq0$, $\omega _k\geq0$ and $\mu _k\geq0$ are the dual variables associated with the constraints given by $\left(25\rm{b}\right)$ - $\left(25\rm{g}\right)$, respectively.
